import subprocess

def grep_file(pattern, path):
    try:
        # Run the grep command using subprocess
        result = subprocess.run(['grep', pattern, path], check=True, text=True, capture_output=True)
        # Return the list of matching lines
        return result.stdout.splitlines()
    except subprocess.CalledProcessError as e:
        # Return an empty list if no matches are found or an error occurs
        return []
