import subprocess

def disk_usage(directory):
    try:
        # Run the 'du -sh' command to get the disk usage of the directory
        result = subprocess.check_output(['du', '-sh', directory], stderr=subprocess.STDOUT)
        # Decode the result from bytes to string and strip any extra whitespace
        return result.decode('utf-8').strip()
    except subprocess.CalledProcessError as e:
        # Return the error output if the command fails
        return e.output.decode('utf-8').strip()
