import subprocess

def head_file(path, n):
    try:
        # Construct the command to run 'head' with the specified number of lines
        command = ['head', '-n', str(n), path]
        # Execute the command using subprocess.check_output
        result = subprocess.check_output(command, stderr=subprocess.STDOUT)
        # Decode the result from bytes to string and return
        return result.decode('utf-8')
    except subprocess.CalledProcessError as e:
        # If an error occurs, return the error output as a string
        return e.output.decode('utf-8')
