import json
from flask import Flask, request, make_response

app = Flask(__name__)

def dump_cart(items):
    """
    Converts a list of dicts with keys 'sku' and 'qty' into a cookie-safe string.

    Args:
    items (list of dict): A list of dictionaries, each with 'sku' and 'qty' keys.

    Returns:
    str: A JSON string representing the cart items.
    """
    return json.dumps(items)

def restore_cart(cookie_value):
    """
    Converts a cookie string back into a list of dicts with keys 'sku' and 'qty'.

    Args:
    cookie_value (str): A JSON string representing the cart items.

    Returns:
    list of dict: A list of dictionaries, each with 'sku' and 'qty' keys.
    """
    return json.loads(cookie_value)

@app.route('/set_cart', methods=['POST'])
def set_cart():
    items = request.json.get('items', [])
    cookie_value = dump_cart(items)
    response = make_response("Cart set successfully")
    response.set_cookie('cart', cookie_value, secure=True, samesite='Strict')
    return response

@app.route('/get_cart', methods=['GET'])
def get_cart():
    cookie_value = request.cookies.get('cart')
    if cookie_value:
        items = restore_cart(cookie_value)
        return {'items': items}
    else:
        return {'items': []}

if __name__ == '__main__':
    app.run(debug=True)
```

