        return 1;
    }

    // Copy the key and value
    strncpy(key, line, equals - line);
    key[equals - line] = '\0';
    strcpy(value, equals + 1);

    // Print the results
    printf("key: %s\n", key);
    printf("value: %s\n", value);

    return 0;
