import json

def fetch_weather(city, api_key):
    url = "https://api.example.com/v1/weather"
    headers = {
        "X-API-Key": api_key
    }
    payload = {
        "city": city
    }

    try:
        response = requests.post(url, headers=headers, json=payload)
        response.raise_for_status()  # Raise an exception for 4xx or 5xx status codes
