#include <stdio.h>
#include <string.h>

void format_log_entry(char *out, size_t out_len, const char *level, const char *message) {
    // Calculate the total size needed for the log entry
    size_t total_size = strlen("[") + strlen(level) + strlen("] ") + strlen(message) + 1;

    // Check if the output buffer is large enough
    if (out_len < total_size) {
        // Buffer is too small, truncate the message
        snprintf(out, out_len, "[%.*s] %.*s", (int)(out_len - strlen("[") - 2 - strlen("] ") - 1), level, (int)(out_len - strlen("[") - 2 - strlen("] ") - strlen(level) - 2), message);
    } else {
