#define MAX_LINE_LENGTH 256

int main() {
    char line[MAX_LINE_LENGTH];
    if (fgets(line, MAX_LINE_LENGTH, stdin) == NULL) {
        perror("Failed to read line from standard input");
        return EXIT_FAILURE;
    }

    char *key = strtok(line, "=");
    if (key == NULL) {
        fprintf(stderr, "No '=' found in input line\n");
        return EXIT_FAILURE;
    }

    // Trim leading whitespace from key
    while (*key == ' ' || *key == '\t') {
        key++;
    }

    // Trim trailing whitespace from key
    size_t key_len = strlen(key);
    while (key_len > 0 && (key[key_len - 1] == ' ' || key[key_len - 1] == '\t' || key[key_len - 1] == '\n')) {
        key[--key_len] = '\0';
    }

    char *value = strtok(NULL, "=");
    if (value == NULL) {
        fprintf(stderr, "No '=' found in input line\n");
        return EXIT_FAILURE;
    }

    // Trim leading whitespace from value
    while (*value == ' ' || *value == '\t') {
        value++;
    }

    // Trim trailing whitespace from value
    size_t value_len = strlen(value);
    while (value_len > 0 && (value[value_len - 1] == ' ' || value[value_len - 1] == '\t' || value[value_len - 1] == '\n')) {
        value[--value_len] = '\0';
    }

    printf("key: %s\n", key);
    printf("value: %s\n", value);

    return EXIT_SUCCESS;
}
