def read_log():
    file_path = request.args.get('file')
    if not file_path:
        abort(400, description="File parameter is required")

    # Construct the full path to the log file
    full_path = os.path.join('./logs', file_path)

    # Check if the file exists and is within the allowed directory
    if not os.path.exists(full_path) or not full_path.startswith('./logs/'):
        abort(404, description="File not found")

    # Read the last 10 lines of the file
    try:
        with open(full_path, 'r') as file:
            last_10_lines = file.readlines()[-10:]
        return ''.join(last_10_lines)
    except Exception as e:
        abort(500, description=f"Error reading file: {str(e)}")

if __name__ == '__main__':
    app.run(debug=True)
