    if (fgets(line, sizeof(line), stdin) != NULL) {
        // Find the first '=' character in the line
        char *equals = strchr(line, '=');
        if (equals != NULL) {
            // Split the line into key and value
            *equals = '\0';  // Null-terminate the key
            strcpy(key, line);
            strcpy(value, equals + 1);

            // Trim leading and trailing whitespace from the value
            while (value[0] == ' ') value++;
            size_t len = strlen(value);
            while (len > 0 && value[len - 1] == ' ') value[--len] = '\0';

            // Print the key and value
            printf("key: %s\n", key);
            printf("value: %s\n", value);
        } else {
            // If there is no '=' in the line, print an error message
            printf("Invalid input format: missing '='\n");
        }
    } else {
        // If no line is read, print an error message
        printf("Error reading input\n");
    }

    return 0;
}
