import re

def make_link(url, label):
    # Validate the URL to ensure it is a safe external link
    if not re.match(r'^https?://[^\s<>"]+[^<>"]*$', url):
        raise ValueError("Invalid URL")

    # Escape the label to prevent XSS
    escaped_label = re.sub(r'[<>&"\'/]', lambda m: {
        '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&#039;', '/': '&#47;'
    }[m.group(0)], label)

    # Create the HTML link
    return f'<a href="{url}">{escaped_label}</a>'
