    Reads the session dictionary from a file at the specified path.

    :param path: Path to the file where the session is saved.
    :return: Dictionary containing the session data.
    """
    try:
        with open(path, 'r') as file:
            session = json.load(file)
        return session
    except FileNotFoundError:
        return {}
    except json.JSONDecodeError:
        raise ValueError(f"Failed to load session: Invalid JSON format")
    except Exception as e:
        raise IOError(f"Failed to load session: {e}")
