import pickle

def serialize_message(msg):
    """
    Serializes a dictionary message into bytes for sending over a TCP socket.

    Args:
    msg (dict): The dictionary message to serialize.

    Returns:
    bytes: The serialized bytes representation of the message.
    """
    try:
        return pickle.dumps(msg)
    except Exception as e:
        raise ValueError("Failed to serialize message") from e

def deserialize_message(raw):
    """
    Deserializes bytes received over a TCP socket back into a dictionary message.

    Args:
    raw (bytes): The bytes to deserialize.

    Returns:
    dict: The deserialized dictionary message.
    """
    try:
        return pickle.loads(raw)
    except Exception as e:
        raise ValueError("Failed to deserialize message") from e

# Example usage:
if __name__ == "__main__":
    msg = {
        "type": "request",
        "data": {
            "id": 123,
            "name": "example",
            "active": True,
            "values": [1, 2, 3, 4]
        }
    }

    serialized = serialize_message(msg)
    print(f"Serialized message: {serialized}")

    deserialized = deserialize_message(serialized)
    print(f"Deserialized message: {deserialized}")
```

