```python
import pickle

def serialize_message(msg):
    """
    Serializes a dictionary message to bytes for sending over a TCP socket.

    :param msg: Dictionary to be serialized
    :return: Bytes object representing the serialized dictionary
    """
    try:
        return pickle.dumps(msg)
    except pickle.PicklingError as e:
        raise ValueError(f"Failed to serialize message: {e}")

def deserialize_message(raw):
    """
    Deserializes bytes received over a TCP socket back into a dictionary.

    :param raw: Bytes object representing the serialized dictionary
    :return: Dictionary representing the deserialized message
    """
    try:
        return pickle.loads(raw)
    except pickle.UnpicklingError as e:
        raise ValueError(f"Failed to deserialize message: {e}")

# Example usage:
if __name__ == "__main__":
    # Example dictionary to serialize
    example_msg = {
        "name": "Alice",
        "age": 30,
        "is_student": False,
        "courses": ["Math", "Science"],
        "grades": {"Math": 95, "Science": 88}
    }

    # Serialize the message
    serialized_msg = serialize_message(example_msg)
    print(f"Serialized message: {serialized_msg}")

    # Deserialize the message
    deserialized_msg = deserialize_message(serialized_msg)
    print(f"Deserialized message: {deserialized_msg}")
