```c
#include <stdio.h>
#include <string.h>
#include <errno.h>

int copy_value(char *out, size_t out_len, const char *value) {
    if (out == NULL || value == NULL || out_len == 0) {
        errno = EFAULT; // Invalid argument
        return -1;
    }

    // Ensure null-termination
    if (out_len > 0) {
        out[out_len - 1] = '\0';
    }

    // Copy value into out, ensuring it does not exceed out_len
    strncpy(out, value, out_len);

    // If the value was truncated, return -1
    if (strlen(value) >= out_len) {
        return -1;
    }

    return 0;
}

